create table if not exists dbo.agent_dividends
(
    id                                          integer generated by default as identity
        constraint pk_agent_dividends_id
            primary key,
    agent_id                                    uuid                        not null,
    brand_id                                    uuid                        not null,
    "from"                                      timestamp with time zone    not null,
    "to"                                        timestamp with time zone    not null,
    deposit_amount                              numeric(18, 6)              not null,
    withdrawal_amount                           numeric(18, 6)              not null,
    company_adjust_amount                       numeric(18, 6)              not null,
    bonus_amount                                numeric(18, 6)              not null,
    bet_amount                                  numeric(18, 6)              not null,
    turnover                                    numeric(18, 6)              not null,
    win_loss_amount                             numeric(18, 6)              not null,
    net_profit                                  numeric(18, 6)              not null,
    live_dealer_win_loss                        numeric(18, 6)              not null,
    slot_win_loss                               numeric(18, 6)              not null,
    fishing_win_loss                            numeric(18, 6)              not null,
    arcade_win_loss                             numeric(18, 6)              not null,
    table_game_win_loss                         numeric(18, 6)              not null,
    lottery_win_loss                            numeric(18, 6)              not null,
    card_game_win_loss                          numeric(18, 6)              not null,
    sports_win_loss                             numeric(18, 6)              not null,
    e_sports_win_loss                           numeric(18, 6)              not null,
    virtual_sports_win_loss                     numeric(18, 6)              not null,
    agent_dividend_percentage                   numeric(9, 6)               not null,
    agent_dividend_amount                       numeric(18, 6)              not null,
    sent_on                                     timestamp with time zone,
    created_on                                  timestamp with time zone    not null,
    referenced_agent_dividend_id                integer,
    before_dividend_amount                      numeric(18, 6),
    promotion_amount                            numeric(18, 6) default 0.0  not null,
    rebate_amount                               numeric(18, 6) default 0.0  not null,
    original_turnover                           numeric(18, 6) default 0.0  not null,
    valid_bet_amount                            numeric(18, 6) default 0.0  not null,
    agent_adjust_amount                         numeric(18, 6) default 0.0  not null,
    no_include_net_profit_agent_adjust_amount   numeric(18, 6) default 0.0  not null,
    no_include_net_profit_company_adjust_amount numeric(18, 6) default 0.0  not null,
    bonus_adjust_amount                         numeric        default 0.0  not null,
    no_include_net_profit_bonus_adjust_amount   numeric(18, 6) default 0.0  not null,
    deposit_handling_fee                        numeric(18, 6) default 0.0  not null,
    withdraw_handling_fee                       numeric(18, 6) default 0.0  not null,
    active_number                               integer        default 0    not null,
    platform_charge_percentage                  numeric(18, 6) default 0.0  not null,
    negative_agent_dividend_carry_forward       boolean        default true not null
);

create index if not exists ix_agent_dividends_agent_id_brand_id_created_on
    on dbo.agent_dividends (agent_id, brand_id, created_on);

create index if not exists ix_agent_dividends_agent_id_sent_on
