        constraint pk_brands
            primary key,
    status                                    smallint                                                                            not null,
    description                               varchar(256),
    operational_email                         varchar(128),
    time_zone_id                              varchar(256),
    licensee_id                               uuid                                                                                not null
        constraint fk_brands_licensees_licensee_id
            references dbo.licensees
            on delete cascade,
    client_id                                 varchar(128)                                                                        not null,
    secret_key                                varchar(32)                                                                         not null,
    api_key                                   varchar(64)                                                                         not null,
    settlement_interval_type                  smallint                 default 0                                                  not null,
    previous_settlement_from                  timestamp with time zone default '0001-01-01 00:00:00+00'::timestamp with time zone not null,
