create table if not exists dbo.brand_payment_vip_levels
(
    brand_payment_id uuid not null
        constraint fk_brand_payment_vip_levels_brand_payments_brand_payment_id
            references dbo.brand_payments
            on delete cascade,
    vip_level_id     uuid not null
        constraint fk_brand_payment_vip_levels_vip_levels_vip_level_id
            references dbo.vip_levels
            on delete cascade,
    constraint pk_brand_payment_vip_levels
        primary key (brand_payment_id, vip_level_id)
);

create index if not exists ix_brand_payment_vip_levels_vip_level_id
    on dbo.brand_payment_vip_levels (vip_level_id);

create table if not exists dbo.players
(
    player_code                  varchar(16)                not null
        constraint pk_player_code
            primary key,
    id_number                    varchar(50),
    username                     varchar(32)                not null,
    real_name                    varchar(256),
    password                     bytea                      not null,
    salt                         bytea                      not null,
    withdraw_password            bytea                      not null,
    withdraw_salt                bytea                      not null,
    default_wallet_id            uuid                       not null,
    default_wallet_currency_code varchar(16)                not null,
    brand_id                     uuid                       not null
        constraint fk_players_brands_brand_id
            references dbo.brands
            on delete cascade,
    registered_on                timestamp with time zone,
    last_active_on               timestamp with time zone   not null,
    status                       smallint                   not null,
    bet_limit_id                 integer                    not null
        constraint fk_players_bet_limits_bet_limit_id
            references dbo.bet_limits
            on delete restrict,
    type                         smallint                   not null,
    email                        varchar(64),
    phone                        varchar(32),
    qq                           varchar(64),
    wechat                       varchar(64),
    agent_id                     uuid
        constraint fk_players_agents_agent_id
            references dbo.agents
            on delete restrict,
    identity_authentication      boolean                    not null,
    phone_authentication         boolean                    not null,
    accumulated_deposit          numeric(18, 6) default 0.0 not null,
    vip_id                       uuid
        constraint fk_players_vip_levels_vip_id
            references dbo.vip_levels
            on delete restrict,
    updated_by_username          text,
    updated_on                   timestamp with time zone   not null,
    first_deposit_on             timestamp with time zone,
    area_code                    varchar(10),
    first_promotion_on           timestamp with time zone,
    remark                       text,
    birthdate                    date,
    birthday                     varchar(4) generated always as ((
        lpad((date_part('month'::text, birthdate))::text, 2, '0'::text) ||
        lpad((date_part('day'::text, birthdate))::text, 2, '0'::text))) stored,
    snapshot_event_id            uuid
);

