create table if not exists dbo.promotions
(
    id                       uuid                        not null
        constraint pk_promotions_id
            primary key,
    name                     varchar(64)                 not null,
    "from"                   timestamp with time zone    not null,
    "to"                     timestamp with time zone    not null,
    status                   smallint                    not null,
    auto_sent_player_bonus   boolean                     not null,
    brand_id                 uuid                        not null
        constraint fk_promotions_brands_brand_id
            references dbo.brands
            on delete cascade,
    promotion_type           text                        not null,
    settlement_interval_type text,
    total_amount_limit       numeric(18, 6)              not null,
    amount_used              numeric(18, 6)              not null,
    unlimited                smallint                    not null,
    game_type                smallint,
    percentage               numeric(9, 6)               not null,
    bonus_amount_limit       numeric(18, 6)              not null,
    turnover_multiple        numeric(18, 6)              not null,
    created_on               timestamp with time zone    not null,
    updated_on               timestamp with time zone    not null,
    created_by_username      text,
    updated_by_username      text,
    vip_level_id             uuid
        constraint fk_promotions_vip_levels_vip_level_id
            references dbo.vip_levels
            on delete restrict,
    content                  text,
    desktop_banner           varchar(128),
    localization             jsonb,
    mobile_banner            varchar(128),
    sub_subject              varchar(2048),
    terms                    text,
    campaign_detail          jsonb   default '{}'::jsonb not null,
    display_order            integer default 1           not null,
    amount_used_snapshot_id  uuid,
    snapshot_event_id        uuid
);

create index if not exists ix_promotions_brand_id
    on dbo.promotions (brand_id);

create index if not exists ix_promotions_vip_level_id
    on dbo.promotions (vip_level_id);

create table if not exists dbo.agent_transactions
(
    id                      uuid                       not null
        constraint pk_agent_transactions
            primary key,
    agent_id                uuid                       not null,
    wallet_id               uuid                       not null
        constraint fk_agent_transaction_wallet_id
            references dbo.agent_wallets
            on delete cascade,
    brand_id                uuid                       not null
        constraint fk_agent_transactions_brands_brand_id
            references dbo.brands
            on delete cascade,
    external_transaction_id text,
    amount                  numeric(18, 6)             not null,
    balance                 numeric(18, 6)             not null,
    description             text,
    type                    smallint                   not null,
    recorded_on             timestamp with time zone   not null,
    sent_on                 timestamp with time zone,
    lock_amount             numeric(18, 6) default 0.0 not null,
    locked_balance          numeric(18, 6) default 0.0 not null
);

create index if not exists ix_agent_transactions_agent_id
    on dbo.agent_transactions (agent_id);

create index if not exists ix_agent_transactions_brand_id
    on dbo.agent_transactions (brand_id);

create index if not exists ix_agent_transactions_wallet_id
    on dbo.agent_transactions (wallet_id);

create table if not exists dbo.brand_group_game_provider_bet_limits
(
    brand_group_bet_limit_id   uuid not null
        constraint fk_brand_group_game_provider_bet_limits_brand_group_bet_limits_
            references dbo.brand_group_bet_limits
            on delete cascade,
    game_provider_bet_limit_id uuid not null
        constraint fk_brand_group_game_provider_bet_limits_game_provider_bet_limit
            references dbo.game_provider_bet_limits
            on delete cascade,
    constraint pk_brand_group_game_provider_bet_limits
        primary key (brand_group_bet_limit_id, game_provider_bet_limit_id)
