create table if not exists dbo.game_bet_firsts
(
    game_provider_id               uuid                                                                                not null,
    game_id                        integer                                                                             not null,
    wallet_id                      uuid                                                                                not null,
    external_bet_id                varchar(255)                                                                        not null,
    external_created_on            timestamp with time zone default '1970-01-01 00:00:00+00'::timestamp with time zone not null,
    id                             uuid                                                                                not null,
    game_bet_id                    uuid                                                                                not null,
    game_provider_configuration_id uuid                                                                                not null,
    reseller_id                    uuid                                                                                not null,
    licensee_id                    uuid                                                                                not null,
    brand_id                       uuid                                                                                not null,
    player_code                    text                                                                                not null,
    currency_code                  varchar(16)                                                                         not null,
    external_round_id              varchar(255)                                                                        not null,
    external_closed_on             timestamp with time zone default '1970-01-01 00:00:00+00'::timestamp with time zone not null,
    external_payoff_on             timestamp with time zone default '1970-01-01 00:00:00+00'::timestamp with time zone not null,
    external_resettle_on           timestamp with time zone default '1970-01-01 00:00:00+00'::timestamp with time zone not null,
    bet_state                      integer                  default 0                                                  not null,
    bet_type                       integer                  default 0                                                  not null,
    free_game_state                integer                  default 0                                                  not null,
    gamble_state                   integer                  default 0                                                  not null,
    cashout_state                  integer                  default 0                                                  not null,
    resettle_state                 integer                  default 0                                                  not null,
    jackpot_state                  integer                  default 0                                                  not null,
    currency_ratio                 numeric(18, 6)           default 0.0                                                not null,
    bet                            numeric(18, 6)           default 0.0                                                not null,
    valid_bet                      numeric(18, 6)           default 0.0                                                not null,
    settle                         numeric(18, 6)           default 0.0                                                not null,
    commission                     numeric(18, 6)           default 0.0                                                not null,
    turnover                       numeric(18, 6)           default 0.0                                                not null,
    win_loss                       numeric(18, 6)           default 0.0                                                not null,
    jackpot                        numeric(18, 6)           default 0.0                                                not null,
    created_on                     timestamp with time zone default CURRENT_TIMESTAMP                                  not null,
    closed_on                      timestamp with time zone default CURRENT_TIMESTAMP                                  not null,
    updated_on                     timestamp with time zone default CURRENT_TIMESTAMP                                  not null,
    first_on                       timestamp with time zone default CURRENT_TIMESTAMP                                  not null,
    additional_data                jsonb                    default '{}'::jsonb                                        not null,
    constraint pk_game_bet_firsts
        primary key (external_created_on, game_provider_id, game_id, wallet_id, external_bet_id)
);

