create or replace view bet.vw_valid_game_actions
            (id, external_transaction_id, type, round_id, referenced_game_action_id, game_action_batch_id, recorded_on,
             external_bet_id, sent_on, player_ip, turnover, win_loss, unsettled_bets, is_closing_round,
             closing_round_explicit_request, amount, external_game_action_group_id, balance, bet_type, extra_data)
as
SELECT ga.id,
       ga.external_transaction_id,
       ga.type,
       ga.round_id,
       ga.referenced_game_action_id,
       ga.game_action_batch_id,
       ga.recorded_on,
       ga.external_bet_id,
       ga.sent_on,
       ga.player_ip,
       ga.turnover,
       ga.win_loss,
       ga.unsettled_bets,
       ga.is_closing_round,
       ga.closing_round_explicit_request,
       ga.amount,
       ga.external_game_action_group_id,
       ga.balance,
       ga.bet_type,
       ga.extra_data
FROM bet.game_actions ga
WHERE ga.type <> 5
  AND NOT (EXISTS (SELECT 1
                   FROM bet.game_actions ref
                   WHERE ref.type = 5
                     AND ref.referenced_game_action_id = ga.id
                     AND ref.round_id = ga.round_id
                     AND NOT (EXISTS (SELECT 1
                                      FROM bet.game_actions cancel
                                      WHERE cancel.type = 5
                                        AND cancel.referenced_game_action_id = ref.id
                                        AND cancel.round_id = ref.round_id))));

create or replace function bet.game_action_get_game_action_external_ids(game_provider_id uuid,
                                                                        player_code character varying,
                                                                        external_round_id character varying,
                                                                        game_id integer, game_action_types integer[])
    returns TABLE
            (
                "ExternalBetId"                   character varying,
                "ExternalTransactionId"           character varying,
                "ExternalRoundId"                 character varying,
                "ExternalGameActionGroupId"       character varying,
                "GameActionType"                  smallint,
                "Amount"                          numeric,
                "RecordedOn"                      timestamp with time zone,
                "ExternalReferencedTransactionId" character varying,
                "ExternalGameId"                  character varying
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select ga.external_bet_id                                                                                   as "ExternalBetId",
               ga.external_transaction_id                                                                           as "ExternalTransactionId",
               r.external_round_id                                                                                  as "ExternalRoundId",
               ga.external_game_action_group_id                                                                     as "ExternalGameActionGroupId",
               ga."type"                                                                                            as "GameActionType",
               ga.amount                                                                                            as "Amount",
               ga.recorded_on                                                                                       as "RecordedOn",
               (select g.external_transaction_id
                from bet.game_actions g
                where g.id = ga.referenced_game_action_id)                                                          as "ExternalReferencedTransactionId",
               (select g.external_id from dbo.games g where g.id = r.game_id)                                       as "ExternalGameId"
        from bet.game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where r.external_round_id = $3
          and r.game_provider_id = $1
          and r.player_code = $2
          and r.game_id = $4
          and ga."type" = any ($5);

END;
$$;

create or replace function bet.game_action_get_game_actions_by_external_group_id(game_provider_id uuid,
                                                                                 player_code character varying,
                                                                                 external_group_id character varying)
    returns TABLE
            (
                "ExternalBetId"                   character varying,
                "ExternalTransactionId"           character varying,
                "ExternalRoundId"                 character varying,
                "ExternalGameActionGroupId"       character varying,
                "GameActionType"                  smallint,
                "Amount"                          numeric,
                "RecordedOn"                      timestamp with time zone,
                "ExternalReferencedTransactionId" character varying,
                "ExternalGameId"                  character varying
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select ga.external_bet_id                                                                                   as "ExternalBetId",
               ga.external_transaction_id                                                                           as "ExternalTransactionId",
               r.external_round_id                                                                                  as "ExternalRoundId",
               ga.external_game_action_group_id                                                                     as "ExternalGameActionGroupId",
               ga."type"                                                                                            as "GameActionType",
               ga.amount                                                                                            as "Amount",
               ga.recorded_on                                                                                       as "RecordedOn",
               (select g.external_transaction_id
                from bet.game_actions g
                where g.id = ga.referenced_game_action_id)                                                          as "ExternalReferencedTransactionId",
               (select g.external_id from dbo.games g where g.id = r.game_id)                                       as "ExternalGameId"
        from bet.game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where r.game_provider_id = $1
          and r.player_code = $2
          and ga.external_game_action_group_id = $3;

END;
$$;

create or replace function bet.game_action_get_game_actions_by_external_round_id(game_provider_id uuid,
                                                                                 player_code character varying,
                                                                                 external_round_id character varying,
                                                                                 game_id integer)
    returns TABLE
            (
                "Id"                        uuid,
                "ExternalBetId"             character varying,
                "ExternalTransactionId"     character varying,
                "RoundId"                   uuid,
                "ExternalRoundId"           character varying,
                "ExternalGameActionGroupId" character varying,
                "GameActionType"            smallint,
                "Amount"                    numeric,
                "RecordedOn"                timestamp with time zone,
                "ReferencedGameActionId"    uuid,
                "RoundStatus"               smallint,
                "RoundBetAmount"            numeric,
                "RoundValidBetAmount"       numeric,
                "RoundWinLoss"              numeric,
                "Commission"                numeric,
                "TieBetAdjustment"          numeric,
                "RoundClosedOn"             timestamp with time zone
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select ga.id                            as "Id",
               ga.external_bet_id               as "ExternalBetId",
               ga.external_transaction_id       as "ExternalTransactionId",
               r.id                             as "RoundId",
               r.external_round_id              as "ExternalRoundId",
               ga.external_game_action_group_id as "ExternalGameActionGroupId",
               ga."type"                        as "GameActionType",
               ga.amount                        as "Amount",
               ga.recorded_on                   as "RecordedOn",
               ga.referenced_game_action_id     as "ReferencedGameActionId",
               r.status                         as "RoundStatus",
               r.bet_amount                     as "RoundBetAmount",
               r.valid_bet_amount               as "RoundValidBetAmount",
               r.win_loss                       as "RoundWinLoss",
               r.commission                     as "Commission",
               r.tie_bet_adjustment             as "TieBetAdjustment",
               r.closed_on                      as "RoundClosedOn"
        from bet.game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where r.external_round_id = $3
          and r.player_code = $2
          and r.game_provider_id = $1
          and r.game_id = $4;

END;
$$;

create or replace function bet.game_action_get_game_actions_by_external_transaction_id(game_provider_id uuid,
                                                                                       player_code character varying,
                                                                                       external_transaction_id character varying)
    returns TABLE
            (
                "ExternalBetId"                   character varying,
                "ExternalTransactionId"           character varying,
                "ExternalRoundId"                 character varying,
                "ExternalGameActionGroupId"       character varying,
                "GameActionType"                  smallint,
                "Amount"                          numeric,
                "RecordedOn"                      timestamp with time zone,
                "ExternalReferencedTransactionId" character varying,
                "ExternalGameId"                  character varying
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select ga.external_bet_id                                                                                   as "ExternalBetId",
               ga.external_transaction_id                                                                           as "ExternalTransactionId",
               r.external_round_id                                                                                  as "ExternalRoundId",
               ga.external_game_action_group_id                                                                     as "ExternalGameActionGroupId",
               ga."type"                                                                                            as "GameActionType",
               ga.amount                                                                                            as "Amount",
               ga.recorded_on                                                                                       as "RecordedOn",
               (select g.external_transaction_id
                from bet.game_actions g
                where g.id = ga.referenced_game_action_id)                                                          as "ExternalReferencedTransactionId",
               (select g.external_id from dbo.games g where g.id = r.game_id)                                       as "ExternalGameId"
        from bet.game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where ga.external_transaction_id = $3
          and r.game_provider_id = $1
          and r.player_code = $2;

END;
$$;

create or replace function bet.game_action_get_game_actions_in_same_round(game_provider_id uuid,
                                                                          player_code character varying,
                                                                          external_round_id character varying,
                                                                          game_id integer)
    returns TABLE
            (
                "GameActionId"                uuid,
                "ReferenceGameActionId"       uuid,
                "ExternalTransactionId"       character varying,
                "ExternalGameActionGroupId"   character varying,
                "Turnover"                    numeric,
                "WinLoss"                     numeric,
                "UnsettledBets"               numeric,
                "IsClosingRound"              boolean,
                "ClosingRoundExplicitRequest" boolean,
                "Type"                        smallint,
                "RoundId"                     uuid,
                "GameId"                      integer,
                "RoundStatus"                 smallint,
                "ExternalRoundId"             character varying,
                "Amount"                      numeric,
                "GameActionRecordedOn"        timestamp with time zone,
                "GameActionSentOn"            timestamp with time zone,
                "BetType"                     character varying,
                "WalletId"                    uuid,
                "JackpotContribution"         jsonb
            )
    language plpgsql
as
$$
BEGIN

    set lock_timeout to 3000;

    RETURN QUERY
        with round as
                 (select r.id,
                         r.game_id,
                         r.status,
                         r.external_round_id,
                         r.wallet_id,
                         r.created_on
                  from bet.rounds r
                  where r.external_round_id = $3
                    and r.player_code = $2
                    and r.game_provider_id = $1
                    and r.game_id = $4
                      for update)
        select ga.id                             as "GameActionId",
               ga.referenced_game_action_id      as "ReferenceGameActionId",
               ga.external_transaction_id        as "ExternalTransactionId",
               ga.external_game_action_group_id  as "ExternalGameActionGroupId",
               ga.turnover                       as "Turnover",
               ga.win_loss                       as "WinLoss",
               ga.unsettled_bets                 as "UnsettledBets",
               ga.is_closing_round               as "IsClosingRound",
               ga.closing_round_explicit_request as "ClosingRoundExplicitRequest",
               ga."type"                         as "Type",
               r.id                              as "RoundId",
               r.game_id                         as "GameId",
               r.status                          as "RoundStatus",
               r.external_round_id               as "ExternalRoundId",
               ga.amount                         as "Amount",
               ga.recorded_on                    as "GameActionRecordedOn",
               ga.sent_on                        as "GameActionSentOn",
               ga.bet_type                       as "BetType",
               r.wallet_id                       as "WalletId",
               ga.jackpot_contribution           as "JackpotContribution"
        from round r
                 join bet.game_actions ga on ga.round_id = r.id
        where ga.recorded_on >= (r.created_on - 5 * interval '1 minute')
        order by ga.recorded_on asc;

END;
$$;

create or replace function bet.game_action_get_valid_game_action_external_ids(game_provider_id uuid,
                                                                              player_code character varying,
                                                                              external_round_id character varying,
                                                                              game_id integer, only_placements boolean)
    returns TABLE
            (
                "ExternalBetId"                   character varying,
                "ExternalTransactionId"           character varying,
                "ExternalRoundId"                 character varying,
                "ExternalGameActionGroupId"       character varying,
                "GameActionType"                  smallint,
                "Amount"                          numeric,
                "RecordedOn"                      timestamp with time zone,
                "ExternalReferencedTransactionId" character varying,
                "ExternalGameId"                  character varying
            )
    language plpgsql
as
$$
begin


    CREATE TEMP TABLE IF NOT EXISTS temp_rounds ON COMMIT drop AS
    select r.id as round_id, r.external_round_id, r.game_id, g.external_id as game_external_id
    from bet.rounds r
             join dbo.games g on r.game_id = g.id
    where r.external_round_id = $3
      and r.player_code = $2
      and r.game_provider_id = $1
      and r.game_id = $4
    order by r.created_on asc
    limit 1;

    CREATE TEMP TABLE IF NOT EXISTS temp_game_actions ON COMMIT drop AS
    select ga.id,
           ga.external_transaction_id,
           ga.external_game_action_group_id,
           ga.external_bet_id,
           ga."type",
           ga.amount,
           ga.round_id,
           ga.recorded_on,
           ga.referenced_game_action_id
    from bet.vw_valid_game_actions ga
    where ga.round_id = (select round_id from temp_rounds)
      and ($5 = false or ga."type" = 0);

    RETURN QUERY
        with act as (select ga1.external_bet_id,
                            ga1.external_transaction_id,
                            ga1.external_game_action_group_id,
                            ga1."type",
                            ga1.amount,
                            ga1.recorded_on,
                            ga2.external_transaction_id as referenced_external_transaction_id,
                            ga1.round_id
                     from temp_game_actions ga1
                              left join temp_game_actions ga2 on ga1.referenced_game_action_id = ga2.id)
        select act.external_bet_id                    as "ExternalBetId",
               act.external_transaction_id            as "ExternalTransactionId",
               r.external_round_id                    as "ExternalRoundId",
               act.external_game_action_group_id      as "ExternalGameActionGroupId",
               act."type"                             as "GameActionType",
               act.amount                             as "Amount",
               act.recorded_on                        as "RecordedOn",
               act.referenced_external_transaction_id as "ExternalReferencedTransactionId",
               r.game_external_id                     as "ExternalGameId"
        from act
                 join temp_rounds r on r.round_id = act.round_id
        order by act.recorded_on asc;

END;
$$;

create or replace function bet.game_action_get_valid_game_action_external_ids_old(game_provider_id uuid,
                                                                                  player_code character varying,
                                                                                  external_round_id character varying,
                                                                                  game_id integer,
                                                                                  only_placements boolean)
    returns TABLE
            (
                "ExternalBetId"                   character varying,
                "ExternalTransactionId"           character varying,
                "ExternalRoundId"                 character varying,
                "ExternalGameActionGroupId"       character varying,
                "GameActionType"                  smallint,
                "Amount"                          numeric,
                "RecordedOn"                      timestamp with time zone,
                "ExternalReferencedTransactionId" character varying,
                "ExternalGameId"                  character varying
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select ga.external_bet_id                                                                                   as "ExternalBetId",
               ga.external_transaction_id                                                                           as "ExternalTransactionId",
               r.external_round_id                                                                                  as "ExternalRoundId",
               ga.external_game_action_group_id                                                                     as "ExternalGameActionGroupId",
               ga."type"                                                                                            as "GameActionType",
               ga.amount                                                                                            as "Amount",
               ga.recorded_on                                                                                       as "RecordedOn",
               (select g.external_transaction_id
                from bet.game_actions g
                where g.id = ga.referenced_game_action_id)                                                          as "ExternalReferencedTransactionId",
               (select g.external_id from dbo.games g where g.id = r.game_id)                                       as "ExternalGameId"
        from bet.vw_valid_game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where r.external_round_id = $3
          and r.player_code = $2
          and r.game_provider_id = $1
          and r.game_id = $4
          and ($5 = false or ga."type" = 0);

END;
$$;

create or replace function bet.game_action_referenced_game_action_exists(game_provider_id uuid,
                                                                         player_code character varying,
                                                                         external_transaction_id character varying,
                                                                         external_round_id character varying)
    returns TABLE
            (
                "Exists" boolean
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select CASE WHEN count(1) > 0 THEN true ELSE false END as "Exists"
        from bet.game_actions ga
                 join bet.rounds r on r.id = ga.round_id
        where r.external_round_id = $4
          and r.game_provider_id = $1
          and r.player_code = $2
          and ga.external_transaction_id = $3;

END;
$$;

create or replace function dbo.agent_get_all_sub_agents(_agent_path text)
    returns TABLE
            (
                "Id"            uuid,
                "Username"      character varying,
                "ParentAgentId" uuid,
                "Path"          ltree
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        select id              "Id",
               username        "Username",
               parent_agent_id "ParentAgentId",
               path            "Path"
        from dbo.agents
        where _agent_path::ltree @> path;

END;
$$;

create or replace function dbo.agent_update_path(_agent_id uuid, _agent_nlevel integer, _agent_path text,
                                                 _new_agent_path text) returns void
    language plpgsql
as
$$
BEGIN

    WITH agentPath AS (select id, nlevel(path) nlevel, path
                       from dbo.agents
                       where _agent_path::ltree @> path
                         and id != _agent_id)

    update dbo.agents
    set "path" = case
                     when _new_agent_path is null
                         then subltree(ap.path, _agent_nlevel - 1, nlevel)::ltree
                     else concat(_new_agent_path, '.', subltree(ap.path, _agent_nlevel - 1, nlevel))::ltree
        end
    from agentPath ap
    where dbo.agents.id = ap.id;

END;
$$;

create or replace function dbo.agent_wallet_update_wallet_balance(agent_id uuid, wallet_id uuid, amount numeric,
                                                                  updated_on timestamp with time zone) returns numeric
    language plpgsql
as
$$
declare
    row_count int;
    bal       decimal;
BEGIN

    set lock_timeout to 3000;

    update dbo.agent_wallets w
    set balance    = w.balance + $3,
        updated_on = $4
    where w.id = $2
      and w.agent_id = $1
    returning balance into bal;

    get diagnostics row_count = ROW_COUNT;

    if row_count = 0 then
        raise exception 'agent wallet not found.' using ERRCODE = '5000';
    end if;

    return bal;

END;
$$;

create or replace function dbo.brand_game_providers_status_changes(_to_maintenance_text text, _to_active_text text) returns void
    language plpgsql
as
$$
declare
    to_maintenance_ids uuid[];
    to_active_ids      uuid[];
BEGIN

    to_maintenance_ids = string_to_array(_to_maintenance_text, ',');
    to_active_ids = string_to_array(_to_active_text, ',');

    update dbo.brand_game_providers
    set status = 3
    where id = ANY (to_maintenance_ids);

    update dbo.brand_game_providers
    set status = 0
    where id = ANY (to_active_ids);

END;
$$;

create or replace function dbo.brand_get_brand_for_cache(brand_id uuid)
    returns TABLE
            (
                "Id"           uuid,
                "Code"         character varying,
                "Name"         character varying,
                "TimeZoneId"   character varying,
                "Status"       smallint,
                "ClientId"     character varying,
                "SecretKey"    character varying,
                "LicenseeId"   uuid,
                "LicenseeCode" character varying,
                "ResellerId"   uuid,
                "ResellerCode" character varying
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        with brand as
                 (select id,
                         time_zone_id,
                         code,
                         "name",
                         status,
                         client_id,
                         secret_key,
                         licensee_id
                  from dbo.brands
                  where id = $1)
        select b.id           as "Id",
               b.code         as "Code",
               b."name"       as "Name",
               b.time_zone_id as "TimeZoneId",
               b.status       as "Status",
               b.client_id    as "ClientId",
               b.secret_key   as "SecretKey",
               l.id           AS "LicenseeId",
               l.code         AS "LicenseeCode",
               r.id           AS "ResellerId",
               r.code         AS "ResellerCode"
        from brand b
                 join dbo.licensees l on l.id = b.licensee_id
                 join dbo.resellers r on r.id = l.reseller_id;
END;
$$;

