create or replace function dbo.localization_get_localization_by_game_provider_id(game_provider_id uuid)
    returns TABLE
            (
                "Context"      character varying,
                "Key"          character varying,
                "CultureCode"  character varying,
                "Transalation" character varying
            )
    language plpgsql
as
$$
begin

    drop table if exists contexts cascade;

    create temp table contexts as
    select id::varchar as "value"
    from dbo.games g
    where g.game_provider_id = $1
    union
    select $1::varchar;

    return QUERY
        select distinct ls.context       as "Context",
                        ls."key"         as "Key",
                        ls.culture_code  as "CultureCode",
                        ls."translation" as "Transalation"
        from dbo.localized_strings ls
                 join contexts ct on ls."key" = ct."value";

END;
$$;

create or replace procedure dbo.player_deauthorize_by_login_record_id(IN player_code character varying, IN login_record_id uuid)
    language plpgsql
as
$$
begin

    update dbo.player_login_records plr
    set status = 1
    where plr.id = $2
      and plr.player_code = $1
      and plr.status = 0
      and plr.expired_on >= now();

END;
$$;

create or replace procedure dbo.player_deauthorize_by_platform_type(IN player_code character varying, IN platform_type smallint)
    language plpgsql
as
$$
begin

    update dbo.player_login_records plr
    set status = 1
    where plr.player_code = $1
      and (plr.platform_type = $2 or $2 is null)
      and plr.status = 0
      and plr.expired_on >= now();

END;
$$;

create or replace function dbo.player_get_player_for_cache(player_code character varying)
    returns TABLE
            (
                "BrandId"                   uuid,
                "Type"                      smallint,
                "Username"                  character varying,
                "Status"                    smallint,
                "DefaultWalletId"           uuid,
                "BetLimitId"                integer,
                "PlayerCode"                character varying,
                "BrandCode"                 character varying,
                "DefaultWalletCurrencyCode" character varying,
                "ExternalCurrencyCode"      character varying
            )
    language plpgsql
as
$$
begin

    RETURN QUERY
        with player as
                 (select p.brand_id,
                         p."type",
                         p.username,
                         p.status,
                         p.default_wallet_id,
                         p.bet_limit_id,
                         p.player_code
                  from dbo.players p
                  where p.player_code = $1)
        select p.brand_id               as "BrandId",
               p."type"                 as "Type",
               p.username               as "Username",
               p.status                 as "Status",
               p.default_wallet_id      as "DefaultWalletId",
               p.bet_limit_id           as "BetLimitId",
               p.player_code            as "PlayerCode",
               b.code                   as "BrandCode",
               w.currency_code          AS "DefaultWalletCurrencyCode",
               w.external_currency_code as "ExternalCurrencyCode"
        from player p
                 join dbo.brands b on b.id = p.brand_id
                 join dbo.wallets w on w.id = p.default_wallet_id;

END;
$$;

create or replace function dbo.player_get_player_login_records(player_code character varying, statuses integer[],
                                                               "from" timestamp with time zone)
    returns TABLE
            (
                "BrandId"      uuid,
                "PlatformType" smallint,
                "Status"       smallint,
                "CreatedOn"    timestamp with time zone,
                "ExpiredOn"    timestamp with time zone
            )
    language plpgsql
as
$$
begin

    RETURN QUERY
        select plr.brand_id      as "BrandId",
               plr.platform_type as "PlatformType",
               plr.status        as "Status",
               plr.created_on    as "CreatedOn",
               plr.expired_on    as "ExpiredOn"
        from dbo.player_login_records plr
        where plr.player_code = $1
          and plr.created_on >= $3
          and plr.status = any ($2);

END;
$$;

create or replace function dbo.promotion_revert_amount_used(_promotion_id uuid, _amount numeric) returns boolean
    language plpgsql
as
$$
BEGIN

    set lock_timeout to 3000;

    update dbo.promotions
    set amount_used = amount_used - _amount
    where id = _promotion_id;

    return true;

END;
$$;

create or replace function dbo.promotion_update_amount_used(_promotion_id uuid, _amount numeric) returns boolean
    language plpgsql
as
$$
DECLARE
    row_count           int;
    _old_amount         decimal;
    _new_amount         decimal;
    _total_amount_limit decimal;
    _unlimited          boolean;
BEGIN
    set lock_timeout to 3000;

    update dbo.promotions
    set amount_used = amount_used + _amount
    where id = _promotion_id
      AND (
        total_amount_limit > amount_used
            OR
        unlimited > 0
        )
    returning amount_used into _total_amount_limit;

    return _total_amount_limit IS NOT NULL;
END;
$$;

create or replace function dbo.report_generate_brand_game_provider_aggregate_by_closed_on(_from timestamp with time zone,
                                                                                          _to timestamp with time zone,
                                                                                          _brand_id uuid,
                                                                                          _audit_log_id integer,
                                                                                          _created_on timestamp with time zone) returns void
    language plpgsql
as
$$

BEGIN
    WITH rounds AS (SELECT r.brand_id,
                           r.game_provider_id,
                           g.type,
                           r.currency_code,
                           date_trunc('hour', r.closed_on)      report_date,
                           COUNT(1)                             transaction_count,
                           COALESCE(SUM(r.bet_amount), 0)       bet_amount,
                           COALESCE(SUM(r.valid_bet_amount), 0) valid_bet_amount,
                           COALESCE(SUM(r.turnover), 0)         turnover,
                           COALESCE(SUM(r.win_loss), 0)         win_loss,
                           COALESCE(SUM(r.settle_amount), 0)    settle_amount,
                           COALESCE(SUM(r.commission), 0)       commission
                    FROM bet.rounds r
                             JOIN dbo.games g on r.game_id = g.id
                    WHERE r.closed_on >= _from
                      and r.closed_on < _to
                      and r.brand_id = _brand_id
                    GROUP BY 1, 2, 3, 4, 5),
         insert_rows AS (
             INSERT INTO report.brand_game_provider_aggregates (audit_log_id, brand_id, game_provider_id, game_type,
                                                                currency_code, transaction_count, bet_amount,
                                                                valid_bet_amount, turnover, win_loss, settle_amount,
                                                                commission, report_date, created_on)
                 SELECT _audit_log_id,
                        brand_id,
                        game_provider_id,
                        type,
                        currency_code,
                        transaction_count,
                        bet_amount,
                        valid_bet_amount,
                        turnover,
                        win_loss,
                        settle_amount,
                        commission,
                        report_date,
                        _created_on
                 FROM rounds)

    INSERT
    INTO report.brand_game_provider_aggregate_records (audit_log_id, brand_id, "data", created_on)
    SELECT _audit_log_id,
           _brand_id,
           (select case when count(1) > 0 then jsonb_agg(rounds) else '[]' end FROM rounds),
           _created_on;
END;
$$;

create or replace function dbo.report_generate_game_provider_aggregate_by_external_closed_on(_from timestamp with time zone,
                                                                                             _to timestamp with time zone,
                                                                                             _game_provider_id uuid,
                                                                                             _audit_log_id integer,
                                                                                             _created_on timestamp with time zone) returns void
    language plpgsql
as
$$

BEGIN
    WITH rounds AS (SELECT r.game_provider_id,
                           r.currency_code,
                           date_trunc('hour', r.external_closed_on) report_date,
                           COUNT(1)                                 transaction_count,
                           COALESCE(SUM(bet_amount), 0)             bet_amount,
                           COALESCE(SUM(valid_bet_amount), 0)       valid_bet_amount,
                           COALESCE(SUM(turnover), 0)               turnover,
                           COALESCE(SUM(win_loss), 0)               win_loss,
                           COALESCE(SUM(settle_amount), 0)          settle_amount,
                           COALESCE(SUM(commission), 0)             commission
                    FROM bet.rounds r
                    WHERE r.external_closed_on >= _from
                      and r.external_closed_on < _to
                      and r.game_provider_id = _game_provider_id
                    GROUP BY 1, 2, 3),
         insert_rows AS (
             INSERT INTO report.game_provider_aggregates (audit_log_id, game_provider_id, currency_code,
                                                          transaction_count, bet_amount, valid_bet_amount, turnover,
                                                          win_loss, settle_amount, commission, report_date, created_on)
                 SELECT _audit_log_id,
                        game_provider_id,
                        currency_code,
                        transaction_count,
                        bet_amount,
                        valid_bet_amount,
                        turnover,
                        win_loss,
                        settle_amount,
                        commission,
                        report_date,
                        _created_on
                 FROM rounds)

    INSERT
    INTO report.game_provider_aggregate_records (audit_log_id, game_provider_id, "data", created_on)
    SELECT _audit_log_id,
           _game_provider_id,
           (select case when count(1) > 0 then jsonb_agg(rounds) else '[]' end FROM rounds),
           _created_on;

END;
$$;

create or replace function dbo.report_get_player_account_change_records(_from timestamp with time zone,
                                                                        _to timestamp with time zone,
                                                                        _player_code character varying,
                                                                        _transaction_type integer DEFAULT NULL::integer,
                                                                        _game_action_type integer DEFAULT NULL::integer,
                                                                        _page_size integer DEFAULT 10,
                                                                        _page_number integer DEFAULT 1)
    returns TABLE
            (
                "TransactionId"         uuid,
                "GameActionId"          uuid,
                "Amount"                numeric,
                "Balance"               numeric,
                "TransactionType"       smallint,
                "GameActionType"        smallint,
                "RecordedOn"            timestamp with time zone,
                "TotalCount"            bigint,
                "Description"           text,
                "ExternalTransactionId" text
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT TRANSACTION_ID          as "TransactionId",
               GAME_ACTION_ID          as "GameActionId",
               AMOUNT                  as "Amount",
               BALANCE                 as "Balance",
               TRANSACTION_TYPE        as "TransactionType",
               GAME_ACTION_TYPE        as "GameActionType",
               RECORDED_ON             as "RecordedOn",
               count(*) over ()        as "TotalCount",
               DESCRIPTION             as "Description",
               EXTERNAL_TRANSACTION_ID as "ExternalTransactionId"
        FROM (SELECT ID   AS TRANSACTION_ID,
                     NULL AS GAME_ACTION_ID,
                     AMOUNT,
                     BALANCE,
                     TYPE AS TRANSACTION_TYPE,
                     NULL AS GAME_ACTION_TYPE,
                     RECORDED_ON,
                     DESCRIPTION,
                     EXTERNAL_TRANSACTION_ID
              FROM DBO.TRANSACTIONS
              WHERE RECORDED_ON >= _from
                AND RECORDED_ON < _to
                AND (
                  (case
                       when _transaction_type = 0 then ("type" in (0, 1100))
                       when _transaction_type = 1 then ("type" in (1, 2100))
                       when _transaction_type = 9 then ("type" in (9, 2300))
                       when _transaction_type IS null then "type" != 2200
                       else
                           "type" = _transaction_type
                      end) AND _game_action_type IS null)
                AND PLAYER_CODE = _player_code
              UNION ALL
              SELECT NULL AS TRANSACTION_ID,
                     ID   AS GAME_ACTION_ID,
                     AMOUNT,
                     BALANCE,
                     NULL AS TRANSACTION_TYPE,
                     TYPE AS GAME_ACTION_TYPE,
                     RECORDED_ON,
                     NULL as DESCRIPTION,
                     NULL as EXTERNAL_TRANSACTION_ID
              FROM BET.GAME_ACTIONS
              WHERE RECORDED_ON >= _from
                AND RECORDED_ON < _to
                AND ((_game_action_type IS NULL
                  OR "type" = _game_action_type) AND _transaction_type IS NULL)
                AND PLAYER_CODE = _player_code) AS A
        ORDER BY A.RECORDED_ON DESC
        OFFSET (_page_number - 1) * _page_size LIMIT _page_size;

END;
$$;

create or replace function dbo.report_get_player_first_deposit_details(_brand_id uuid, _agent_id uuid,
                                                                       _from timestamp with time zone,
                                                                       _to timestamp with time zone)
    returns TABLE
            (
                "Username"                character varying,
                "FirstDepositOn"          timestamp with time zone,
                "FirstDepositAmount"      numeric,
                "TotalDepositAmount"      numeric,
                "TotalWithdrawAmount"     numeric,
                "DepositSubtractWithdraw" numeric,
                "IpAddress"               character varying
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH depositinterval
                 AS (SELECT df.player_code,
                            CASE
                                WHEN df.actual_amount IS NULL THEN df.amount
                                ELSE df.actual_amount
                                END                         AMOUNT,
                            df.created_on,
                            Row_number()
                            OVER (
                                partition BY df.player_code
                                ORDER BY df.created_on ASC) ROW_NUM
                     FROM dbo.deposit_forms df
                              JOIN dbo.players p ON p.player_code = df.player_code
                     WHERE df.brand_id = _brand_id
                       AND p.agent_id = _agent_id
                       AND df.status = 8000
                       AND df.created_on >= _from
                       AND df.created_on < _to),
             checkfirstdeposit
                 AS (SELECT T.player_code,
                            T.amount,
                            T.created_on,
                            Count(d) BEFORE_COUNT
                     FROM depositinterval T
                              LEFT JOIN dbo.deposit_forms D
                                        ON D.player_code = T.player_code
                                            AND D.created_on < _from
                                            AND D.status = 8000
                     WHERE row_num = 1
                     GROUP BY 1,
                              2,
                              3),
             totaldeposit
                 AS (SELECT T2.player_code,
                            T2.amount,
                            T2.created_on,
                            Sum(D2.amount) TOTAL_DEPOSIT
                     FROM checkfirstdeposit T2
                              LEFT JOIN dbo.deposit_forms D2
                                        ON D2.player_code = T2.player_code
                                            AND D2.status = 8000
                     WHERE before_count = 0
                     GROUP BY 1,
                              2,
                              3),
             totalwithdraw
                 AS (SELECT T3.*,
                            COALESCE(Sum(CASE
                                             WHEN W.actual_amount IS NULL THEN W.amount
                                             ELSE W.actual_amount
                                END), 0) TOTAL_WITHDRAW
                     FROM totaldeposit T3
                              LEFT JOIN dbo.withdraw_forms W
                                        ON W.user_id = T3.player_code
                                            AND W.status = 9000
                     GROUP BY 1,
                              2,
                              3,
                              4)
        SELECT username                       AS "Username",
               created_on                     AS "FirstDepositOn",
               amount                         AS "FirstDepositAmount",
               total_deposit                  AS "TotalDepositAmount",
               total_withdraw                 AS "TotalWithdrawAmount",
               total_deposit - total_withdraw AS "DepositSubtractWithdraw",
               ip                             AS "IpAddress"
        FROM (SELECT P.username,
                     T4.*,
                     I.ip,
                     Rank()
                     OVER (
                         partition BY I.player_code
                         ORDER BY record_on ASC) IP_RANK
              FROM totalwithdraw T4
                       JOIN dbo.players P
                            ON P.player_code = T4.player_code
                       LEFT JOIN dbo.player_ip_records I
                                 ON I.player_code = T4.player_code
                                     AND ip_type = 1) T5
        WHERE ip_rank = 1;
END;
$$;

create or replace function dbo.report_get_player_no_second_deposit_details(_brand_id uuid, _agent_id uuid,
                                                                           _from timestamp with time zone,
                                                                           _to timestamp with time zone)
    returns TABLE
            (
                "Username"                character varying,
                "FirstDepositOn"          timestamp with time zone,
                "FirstDepositAmount"      numeric,
                "TotalDepositAmount"      numeric,
                "TotalWithdrawAmount"     numeric,
                "DepositSubtractWithdraw" numeric,
                "IpAddress"               character varying
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH depositinterval
                 AS (SELECT df.player_code,
                            CASE
                                WHEN df.actual_amount IS NULL THEN df.amount
                                ELSE df.actual_amount
                                END                          AMOUNT,
                            df.created_on,
                            COUNT(df.player_code)
                            OVER (
                                partition BY df.player_code) ROWCOUNT
                     FROM dbo.deposit_forms df
                              JOIN dbo.players p ON p.player_code = df.player_code
                     WHERE df.brand_id = _brand_id
                       AND p.agent_id = _agent_id
                       AND df.status = 8000),
             totaldeposit
                 AS (SELECT T.player_code,
                            T.amount,
                            T.created_on,
                            T.amount TOTAL_DEPOSIT
                     FROM depositinterval T
                     WHERE ROWCOUNT = 1
                       AND t.created_on >= _from
                       AND t.created_on < _to),
             totalwithdraw
                 AS (SELECT T3.*,
                            COALESCE(Sum(CASE
                                             WHEN W.actual_amount IS NULL THEN W.amount
                                             ELSE W.actual_amount
                                END), 0) TOTAL_WITHDRAW
                     FROM totaldeposit T3
                              LEFT JOIN dbo.withdraw_forms W
                                        ON W.user_id = T3.player_code
                                            AND W.status = 9000
                     GROUP BY 1,
                              2,
                              3,
                              4)
        SELECT username                       AS "Username",
               created_on                     AS "FirstDepositOn",
               amount                         AS "FirstDepositAmount",
               total_deposit                  AS "TotalDepositAmount",
               total_withdraw                 AS "TotalWithdrawAmount",
               total_deposit - total_withdraw AS "DepositSubtractWithdraw",
               ip                             AS "IpAddress"
        FROM (SELECT P.username,
                     T4.*,
                     I.ip,
                     Rank()
                     OVER (
                         partition BY I.player_code
                         ORDER BY record_on ASC) IP_RANK
              FROM totalwithdraw T4
                       JOIN dbo.players P
                            ON P.player_code = T4.player_code
                       LEFT JOIN dbo.player_ip_records I
                                 ON I.player_code = T4.player_code
                                     AND ip_type = 1) T5
        WHERE ip_rank = 1;
END;
$$;

create or replace function dbo.report_get_round_aggregates(_from timestamp with time zone, _to timestamp with time zone,
                                                           _report_date timestamp with time zone, _hour integer,
                                                           _minute integer)
    returns TABLE
            (
                "BrandId"        uuid,
                "AgentId"        uuid,
                "GameProviderId" uuid,
                "PlayerCode"     character varying,
                "GameType"       smallint,
                "Username"       character varying,
                "Hour"           integer,
                "Minute"         integer,
                "BetAmount"      numeric,
                "ValidBetAmount" numeric,
                "Turnover"       numeric,
                "WinLoss"        numeric,
                "ReportDate"     timestamp with time zone
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        select p.brand_id              "BrandId",
               p.agent_id              "AgentId",
               g.game_provider_id      "GameProviderId",
               p.player_code           "PlayerCode",
               g.type                  "GameType",
               p.username              "Username",
               _hour                   "Hour",
               _minute                 "Minute",
               sum(r.bet_amount)       "BetAmount",
               sum(r.valid_bet_amount) "ValidBetAmount",
               sum(r.turnover)         "Turnover",
               sum(r.win_loss)         "WinLoss",
               _report_date            "ReportDate"
        from bet.rounds r
                 join dbo.games g on r.game_id = g.id
                 join dbo.players p on r.player_code = p.player_code
        where r.closed_on >= _from
          and r.closed_on < _to
          and r.reopened_on is null
        group by p.brand_id, g.game_provider_id, p.player_code, p.agent_id, p.username, g.type;

END;
$$;

create or replace function dbo.station_letter_insert_players(_brand_id uuid, _station_letter_id uuid) returns void
    language plpgsql
as
$$
BEGIN

    insert into dbo.station_letter_players
    select _station_letter_id, player_code, false, null
    from dbo.players
    where brand_id = _brand_id
      and status = 0;

END;
$$;

create or replace function dbo.wallet_get_balance(wallet_id uuid) returns numeric
    language plpgsql
as
$$
declare
    bal decimal;
begin

    select w.balance
    into bal
    from dbo.wallets w
    where w.id = $1;

    return bal;

END;
$$;

create or replace function dbo.wallet_update_wallet_balance(player_code character varying, wallet_id uuid,
                                                            amount numeric,
                                                            updated_on timestamp with time zone) returns numeric
    language plpgsql
as
$$
DECLARE
    updatedCount int;
    bal          decimal;
BEGIN

    SET LOCK_TIMEOUT TO 3000;

    UPDATE dbo.wallets w
    SET balance    = w.balance + $3,
        updated_on = $4
    WHERE w.id = $2
      AND w.player_code = $1
    RETURNING balance INTO bal;

    GET diagnostics updatedCount = ROW_COUNT;

    IF updatedCount = 0 THEN
        RAISE EXCEPTION 'wallet not found.' USING ERRCODE = '5000';
    END IF;

    RETURN bal;

END;
$$;

create or replace function log.log_get_admin_log(tracking_id uuid)
    returns TABLE
            (
                "RequestHeaders"  text,
                "RequestContent"  text,
                "ResponseHeaders" text,
                "ResponseContent" text
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select a.request_headers  AS "RequestHeaders",
               a.request_content  AS "RequestContent",
               a.response_headers AS "ResponseHeaders",
               a.response_content AS "ResponseContent"
        from log.admin_logs a
        where a.tracking_id = $1;

END;
$$;

create or replace function log.log_get_admin_logs(_from timestamp with time zone, _to timestamp with time zone,
                                                  _tracking_id uuid, _ip text, _path text, _method text,
                                                  _server_name text, _response_code integer, _page_size integer,
                                                  _page_number integer, _sort_by text, _is_desc boolean)
    returns TABLE
            (
                "RecordedOn"      timestamp with time zone,
                "TrackingId"      uuid,
                "Id"              uuid,
                "Ip"              character varying,
                "Path"            character varying,
                "Method"          character varying,
                "Description"     character varying,
                "Exception"       text,
                "StackTrace"      text,
                "InnerException"  text,
                "ServerName"      character varying,
                "ResponseCode"    smallint,
                "ExecutionTimeMs" integer,
                "RequestHeaders"  text,
                "RequestContent"  text,
                "ResponseHeaders" text,
                "ResponseContent" text,
                "TotalCount"      bigint
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        select a.recorded_on       as "RecordedOn",
               a.tracking_id       as "TrackingId",
               a.id                as "Id",
               a.ip                as "Ip",
               a.path              as "Path",
               a.method            as "Method",
               a.description       as "Description",
               a.exception         as "Exception",
               a.stack_trace       as "StackTrace",
               a.inner_exception   as "InnerException",
               a.server_name       as "ServerName",
               a.response_code     as "ResponseCode",
               a.execution_time_ms as "ExecutionTimeMs",
               a.request_headers   AS "RequestHeaders",
               a.request_content   AS "RequestContent",
               a.response_headers  AS "ResponseHeaders",
               a.response_content  AS "ResponseContent",
               count(*) over ()    as "TotalCount"
        from log.admin_logs a
        where a.recorded_on >= _from
          and a.recorded_on < _to
          and (_tracking_id is null or a.tracking_id = _tracking_id)
          and (_ip is null or a.ip = _ip)
          and ((_path is null or _path = '') OR a.path ilike '%' || _path || '%')
          and ((_server_name is null or _server_name = '') OR a.server_name ilike '%' || _server_name || '%')
          and (_method is null or a.method = _method)
          and (_response_code is null or a.response_code = _response_code)
        order by case when _is_desc = false AND _sort_by = 'RecordedOn' then a.recorded_on end asc,
                 case when _is_desc = false AND _sort_by = 'Method' then a.method end asc,
                 case when _is_desc = false AND _sort_by = 'Ip' then a.ip end asc,
                 case when _is_desc = false AND _sort_by = 'Path' then a.path end asc,
                 case when _is_desc = true AND _sort_by = 'RecordedOn' then a.recorded_on end desc,
                 case when _is_desc = true AND _sort_by = 'Method' then a.method end desc,
                 case when _is_desc = true AND _sort_by = 'Ip' then a.ip end desc,
                 case when _is_desc = true AND _sort_by = 'Path' then a.path end desc
        offset (_page_number - 1) * _page_size limit _page_size;

END;
$$;

create or replace function log.log_get_api_log(tracking_id uuid)
    returns TABLE
            (
                "RequestHeaders"  text,
                "RequestContent"  text,
                "ResponseHeaders" text,
                "ResponseContent" text
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select a.request_headers  AS "RequestHeaders",
               a.request_content  AS "RequestContent",
               a.response_headers AS "ResponseHeaders",
               a.response_content AS "ResponseContent"
        from log.api_logs a
        where a.tracking_id = $1;

END;
$$;

create or replace function log.log_get_api_logs(_from timestamp with time zone, _to timestamp with time zone,
                                                _tracking_id uuid, _ip text, _path text, _method text, _prefix text,
                                                _server_name text, _response_code integer, _page_size integer,
                                                _page_number integer, _sort_by text, _is_desc boolean)
    returns TABLE
            (
                "RecordedOn"      timestamp with time zone,
                "TrackingId"      uuid,
                "Id"              uuid,
                "Ip"              character varying,
                "Path"            text,
                "Method"          character varying,
                "Prefix"          character varying,
                "ServerName"      character varying,
                "ResponseCode"    smallint,
                "ExecutionTimeMs" integer,
                "RequestHeaders"  text,
                "RequestContent"  text,
                "ResponseHeaders" text,
                "ResponseContent" text,
                "TotalCount"      bigint
            )
    language plpgsql
as
$$
BEGIN

    RETURN QUERY
        select a.recorded_on       as "RecordedOn",
               a.tracking_id       as "TrackingId",
               a.id                as "Id",
               a.ip                as "Ip",
               a.path              as "Path",
               a.method            as "Method",
               a.prefix            as "Prefix",
               a.server_name       as "ServerName",
               a.response_code     as "ResponseCode",
               a.execution_time_ms as "ExecutionTimeMs",
               a.request_headers   AS "RequestHeaders",
               a.request_content   AS "RequestContent",
               a.response_headers  AS "ResponseHeaders",
               a.response_content  AS "ResponseContent",
               count(*) over ()    as "TotalCount"
        from log.api_logs a
        where a.recorded_on >= _from
          and a.recorded_on < _to
          and (_tracking_id is null or a.tracking_id = _tracking_id)
          and (_ip is null or a.ip = _ip)
          and ((_path is null or _path = '') or a.path ilike '%' || _path || '%')
          and ((_prefix is null or _prefix = '') or a.prefix ilike '%' || _prefix || '%')
          and ((_server_name is null or _server_name = '') or a.server_name ilike '%' || _server_name || '%')
          and (_method is null or a.method = _method)
          and (_response_code is null or a.response_code = _response_code)
        order by case when _is_desc = false AND _sort_by = 'RecordedOn' then a.recorded_on end asc,
                 case when _is_desc = false AND _sort_by = 'Method' then a.method end asc,
                 case when _is_desc = false AND _sort_by = 'Ip' then a.ip end asc,
                 case when _is_desc = false AND _sort_by = 'Path' then a.path end asc,
                 case when _is_desc = true AND _sort_by = 'RecordedOn' then a.recorded_on end desc,
                 case when _is_desc = true AND _sort_by = 'Method' then a.method end desc,
                 case when _is_desc = true AND _sort_by = 'Ip' then a.ip end desc,
                 case when _is_desc = true AND _sort_by = 'Path' then a.path end desc
        offset (_page_number - 1) * _page_size limit _page_size;
END;
$$;

create or replace function log.log_get_log_records(_from timestamp with time zone, _to timestamp with time zone,
                                                   _tracking_id uuid, _server_name text, _level integer,
                                                   _page_size integer, _page_number integer, _sort_by text,
                                                   _is_desc boolean)
    returns TABLE
            (
                "RecordedOn" timestamp with time zone,
                "TrackingId" uuid,
                "Id"         uuid,
                "ServerName" character varying,
                "Level"      integer,
                "Logger"     text,
                "Message"    text,
                "Exception"  text,
                "TotalCount" bigint
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT a.recorded_on    as RecordedOn,
               a.tracking_id    as TrackingId,
               a.id             as Id,
               a.server_name    as ServerName,
               a.level          as Level,
               a.logger         as Logger,
               a.message        as Message,
               a.exception      as Exception,
               count(*) OVER () AS TotalCount
        FROM log.log_records a
        WHERE a.recorded_on >= _from
          AND a.recorded_on < _to
          AND (_tracking_id IS NULL OR a.tracking_id = _tracking_id)
          AND (_level IS NULL OR a.level = _level)
          and ((_server_name is null or _server_name = '') OR a.server_name ilike '%' || _server_name || '%')
        ORDER BY CASE WHEN _is_desc = false AND _sort_by = 'RecordedOn' THEN recorded_on END ASC,
                 CASE WHEN _is_desc = false AND _sort_by = 'Level' THEN level END ASC,
                 CASE WHEN _is_desc = true AND _sort_by = 'RecordedOn' THEN recorded_on END DESC,
                 CASE WHEN _is_desc = true AND _sort_by = 'Level' THEN level END DESC
        Offset (_page_number - 1) * _page_size Limit _page_size;
END
$$;

create or replace function dbo.agent_get_agents_with_team_counts(_brand_id uuid, _username text, _page_size integer,
                                                                 _page_number integer, _sort_by text, _is_desc boolean,
                                                                 _status integer DEFAULT NULL::integer,
                                                                 _type integer DEFAULT NULL::integer,
                                                                 _level_type integer DEFAULT NULL::integer)
    returns TABLE
            (
                "Id"                            uuid,
                "BrandId"                       uuid,
                "Username"                      character varying,
                "RealName"                      character varying,
                "Status"                        smallint,
                "AgentStatus"                   integer,
                "Type"                          smallint,
                "LevelType"                     integer,
                "Balance"                       numeric,
                "CommissionPercentage"          numeric,
                "DividendPercentage"            numeric,
                "LiveDealerRebatePercentage"    numeric,
                "SlotRebatePercentage"          numeric,
                "LotteryRebatePercentage"       numeric,
                "CardGameRebatePercentage"      numeric,
                "SportsRebatePercentage"        numeric,
                "VirtualSportsRebatePercentage" numeric,
                "TeamNumber"                    numeric,
                "PlayerNumber"                  bigint,
                "TotalCount"                    bigint
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH RECURSIVE SUBAGENTS AS (SELECT A.ID,
                                            A.ID                                                  MAIN_ID,
                                            (SELECT COUNT(1)
                                             FROM DBO.PLAYERS
                                             WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT NULL) PLAYER_COUNT
                                     FROM DBO.AGENTS A
                                     WHERE A.BRAND_ID = _brand_id
                                     UNION
                                     SELECT A.ID,
                                            S.MAIN_ID,
                                            (SELECT COUNT(1)
                                             FROM DBO.PLAYERS
                                             WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT NULL) PLAYER_COUNT
                                     FROM DBO.AGENTS A
                                              INNER JOIN SUBAGENTS S ON S.ID = A.PARENT_AGENT_ID
                                     WHERE A.BRAND_ID = _brand_id)
        SELECT A.ID                                                                                   as "Id",
               A.BRAND_ID                                                                             as "BrandId",
               A.USERNAME                                                                             as "Username",
               A.REAL_NAME                                                                            as "RealName",
               A.STATUS                                                                               as "Status",
               A.AGENT_STATUS                                                                         as "AgentStatus",
               A.TYPE                                                                                 as "Type",
               A.LEVEL_TYPE                                                                           as "LevelType",
               (SELECT BALANCE FROM DBO.AGENT_WALLETS WHERE AGENT_ID = A.ID)                          as "Balance",
               A.COMMISSION_PERCENTAGE                                                                as "CommissionPercentage",
               A.DIVIDEND_PERCENTAGE                                                                  as "DividendPercentage",
               A.LIVE_DEALER_REBATE_PERCENTAGE                                                        as "LiveDealerRebatePercentage",
               A.SLOT_REBATE_PERCENTAGE                                                               as "SlotRebatePercentage",
               A.LOTTERY_REBATE_PERCENTAGE                                                            as "LotteryRebatePercentage",
               A.CARD_GAME_REBATE_PERCENTAGE                                                          as "CardGameRebatePercentage",
               A.SPORTS_REBATE_PERCENTAGE                                                             as "SportsRebatePercentage",
               A.VIRTUAL_SPORTS_REBATE_PERCENTAGE                                                     as "VirtualSportsRebatePercentage",
               T.AGENT_COUNT + T.PLAYER_COUNT                                                         as "TeamNumber",
               (SELECT COUNT(*) FROM DBO.PLAYERS WHERE AGENT_ID = A.ID AND REGISTERED_ON IS NOT null) as "PlayerNumber",
               count(*) over ()                                                                       as "TotalCount"
        FROM DBO.AGENTS A
                 INNER JOIN (SELECT G.MAIN_ID,
                                    COUNT(1)            AGENT_COUNT,
                                    SUM(G.PLAYER_COUNT) PLAYER_COUNT
                             FROM (SELECT ID,
                                          MAIN_ID,
                                          PLAYER_COUNT
                                   FROM SUBAGENTS) G
                             GROUP BY G.MAIN_ID) T ON A.ID = T.MAIN_ID
        WHERE A.BRAND_ID = _BRAND_ID
          AND (_STATUS IS NULL OR A.STATUS = _STATUS)
          AND (_TYPE IS NULL OR A.TYPE = _TYPE)
          AND (_LEVEL_TYPE IS NULL OR A.LEVEL_TYPE = _LEVEL_TYPE)
          AND ((_USERNAME IS NULL OR _USERNAME = '') OR A.USERNAME ilike '%' || _USERNAME || '%')
        order by case when _is_desc = false AND lower(_sort_by) = 'username' then a.username end asc,
                 case when _is_desc = false AND lower(_sort_by) = 'status' then a.status end asc,
                 case when _is_desc = true AND lower(_sort_by) = 'username' then a.username end desc,
                 case when _is_desc = true AND lower(_sort_by) = 'status' then a.status end desc
        offset (_page_number - 1) * _page_size limit _page_size;

END;
$$;

create or replace function dbo.report_generate_round_aggregates(_from timestamp with time zone,
                                                                _to timestamp with time zone,
                                                                _report_date timestamp with time zone,
                                                                _created_on timestamp with time zone, _hour integer,
                                                                _minute integer)
    returns TABLE
            (
                "BrandId"          uuid,
                "AgentId"          uuid,
                "GameProviderId"   uuid,
                "PlayerCode"       character varying,
                "GameId"           integer,
                "GameType"         smallint,
                "Username"         character varying,
                "Hour"             integer,
                "Minute"           integer,
                "BetAmount"        numeric,
                "ValidBetAmount"   numeric,
                "OriginalTurnover" numeric,
                "Turnover"         numeric,
                "WinLoss"          numeric,
                "ReportDate"       timestamp with time zone
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH rounds AS (SELECT r.id,
                               r.bet_amount,
                               r.valid_bet_amount,
                               r.turnover,
                               r.win_loss,
                               r.game_id,
                               r.player_code,
                               r.brand_id,
                               r.effective_betting_percentage  AS round_effective_betting_percentage,
                               bg.effective_betting_percentage AS brand_game_effective_betting_percentage
                        FROM bet.rounds r
                                 left join dbo.brand_games bg on bg.brand_id = r.brand_id and bg.game_id = r.game_id
                        WHERE r.closed_on >= _from
                          and r.closed_on < _to
                          and r.reopened_on is null)
                ,
             roundRows AS (select p.brand_id,
                                  p.agent_id,
                                  g.game_provider_id,
                                  p.player_code,
                                  g.id                         "game_id",
                                  g.type                       "game_type",
                                  p.username,
                                  _hour                        "hour",
                                  _minute                      "minute",
                                  sum(r.bet_amount)            "bet_amount",
                                  sum(r.valid_bet_amount)      "valid_bet_amount",
                                  sum(r.turnover)              "original_turnover",
                                  sum(CASE
                                          WHEN r.round_effective_betting_percentage is not null
                                              THEN r.turnover * r.round_effective_betting_percentage / 100
                                          WHEN r.brand_game_effective_betting_percentage is not null
                                              THEN r.turnover * r.brand_game_effective_betting_percentage / 100
                                          ELSE r.turnover END) "turnover",
                                  sum(r.win_loss)              "win_loss",
                                  _report_date                 "report_date",
                                  _created_on                  "created_on",
                                  count(1)                     "round_count"
                           from rounds r
                                    join dbo.games g on r.game_id = g.id
                                    join dbo.players p on r.player_code = p.player_code
                           group by p.brand_id, g.game_provider_id, p.player_code, p.agent_id, p.username, g.id,
                                    g.type),
             insert_rows AS (
                 INSERT INTO report.round_aggregates (brand_id, agent_id, player_code, game_provider_id, game_type,
                                                      hour, minute, bet_amount, valid_bet_amount, original_turnover,
                                                      turnover, win_loss, report_date, created_on, game_id, round_count)
                     SELECT brand_id,
                            agent_id,
                            player_code,
                            game_provider_id,
                            game_type,
                            hour,
                            minute,
                            bet_amount,
                            valid_bet_amount,
                            original_turnover,
                            turnover,
                            win_loss,
                            report_date,
                            created_on,
                            game_id,
                            round_count
                     FROM roundRows)

        SELECT brand_id          "BrandId",
               agent_id          "AgentId",
               game_provider_id  "GameProviderId",
               player_code       "PlayerCode",
               game_id           "GameId",
               game_type         "GameType",
               username          "Username",
               hour              "Hour",
               minute            "Minute",
               bet_amount        "BetAmount",
               valid_bet_amount  "ValidBetAmount",
               original_turnover "OriginalTurnover",
               turnover          "Turnover",
               win_loss          "WinLoss",
               report_date       "ReportDate"
        from roundRows;
END;
$$;

create or replace function dbo.report_get_round_and_set_game_setting_aggregates(_from timestamp with time zone, _to timestamp with time zone)
    returns TABLE
            (
                "RoundId"                    uuid,
                "PlayerCode"                 text,
                "Turnover"                   numeric,
                "EffectiveBettingPercentage" numeric
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH rounds AS (select r.id                                                "round_id",
                               r.player_code,
                               r.turnover,
                               coalesce(bg.effective_betting_percentage, 100.0) AS effective_betting_percentage
                        from bet.rounds r
                                 left join dbo.brand_games bg on bg.brand_id = r.brand_id and bg.game_id = r.game_id
                        where r.closed_on >= _from
                          and r.closed_on < _to
                          and r.reopened_on is null
                          and r.effective_betting_percentage is null),
             update_rounds as (
                 UPDATE bet.rounds r SET effective_betting_percentage = br.effective_betting_percentage
                     FROM rounds br where r.id = br.round_id)

        select round_id                     "RoundId",
               player_code                  "PlayerCode",
               turnover                     "Turnover",
               effective_betting_percentage "EffectiveBettingPercentage"
        from rounds;

END;
$$;

create or replace function report.report_get_daily_brands_revenue()
    returns TABLE
            (
                platform                       text,
                currency_code                  text,
                date                           date,
                active_users_count             numeric,
                daily_order_count              text,
                daily_revenue_usd              text,
                monthly_cumulative_revenue_usd text
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH ExchangeRates AS (SELECT 'PHP' AS currency_code, 0.0177 AS rate_to_usd
                               UNION ALL
                               SELECT 'HKD', 0.1277
                               UNION ALL
                               SELECT 'VND_1000', 0.0398),
             SubQuery AS (SELECT b.code                                                                           AS platform,
                                 bc.currency_code,
                                 ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date AS date,
                                 COUNT(DISTINCT p.player_code)                                                    AS active_users_count,
                                 SUM(p.round_count)                                                               AS daily_order_count_raw,
                                 ROUND(SUM(p.win_loss_amount * er.rate_to_usd), 2)                                AS daily_revenue_usd_raw,
                                 SUM(ROUND(SUM(p.win_loss_amount * er.rate_to_usd), 2)) OVER (
                                     PARTITION BY b.code
                                     ORDER BY ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date ASC
                                     )                                                                            AS monthly_cumulative_revenue_usd
                          FROM report.player_aggregates p
                                   JOIN dbo.brands b ON b.id = p.brand_id
                                   JOIN dbo.brand_currencies bc ON b.id = bc.brand_id
                                   LEFT JOIN ExchangeRates er ON bc.currency_code = er.currency_code
                          WHERE
                              p.report_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '1 day' + INTERVAL '8 hours'
                            AND p.report_date <
                                DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' + INTERVAL '8 hours'
                            AND p.bet_amount > 0
                            AND b.code NOT IN ('Sky8', 'GPI')
                          GROUP BY b.code, bc.currency_code, date)

        SELECT CAST('Total' AS text)                                                   AS platform,
               CAST('' AS text)                                                        AS currency_code,
               (CURRENT_DATE - INTERVAL '1 day')::date                                 AS date,
               SUM(sq.active_users_count)                                              AS active_users_count,
               TO_CHAR(SUM(sq.daily_order_count_raw), 'FM999,999,999,999')             AS daily_order_count,
               TO_CHAR(SUM(sq.daily_revenue_usd_raw), 'FM999,999,999,999.99')          AS daily_revenue_usd,
               TO_CHAR(SUM(sq.monthly_cumulative_revenue_usd), 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
        FROM SubQuery sq
        WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
        UNION ALL
        SELECT CAST(sq.platform AS text),      -- Cast to text
               CAST(sq.currency_code AS text), -- Cast to text
               sq.date,
               sq.active_users_count,
               TO_CHAR(sq.daily_order_count_raw, 'FM999,999,999,999')             AS daily_order_count,
               TO_CHAR(sq.daily_revenue_usd_raw, 'FM999,999,999,999.99')          AS daily_revenue_usd,
               TO_CHAR(sq.monthly_cumulative_revenue_usd, 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
        FROM SubQuery sq
        WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
        order by 2;
END;
$$;

create or replace function report.get_players_adjust_amount(brand_code character varying, p_start_date date,
                                                            p_end_date date, p_type integer)
    returns TABLE
            (
                "玩家用戶名" text,
                "公司調帳"   numeric,
                "派發前餘額" numeric,
                "派發後餘額" numeric,
                "執行時間"   timestamp with time zone,
                "執行者"     text,
                "描述"       text
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT p.username::text     AS "玩家用戶名",
               t.amount             AS "公司調帳",
               t.balance - t.amount AS "派發前餘額",
               t.balance            AS "派發後餘額",
               t.recorded_on        AS "執行時間",
               CASE
                   WHEN u.id IS NULL THEN 'System'::text
                   ELSE u.username::text
                   END              AS "執行者",
               t.description::text  AS "描述"
        FROM dbo.transactions AS t
                 INNER JOIN dbo.players AS p ON t.player_code = p.player_code
                 LEFT JOIN dbo.users AS u ON t.created_by_user_id = u.id
        WHERE t.brand_id = (select id from dbo.brands where code = brand_code)
          AND t.recorded_on >= p_start_date
          AND t.recorded_on < p_end_date
          AND t.type = p_type;
END;
$$;

create or replace function report.get_first_deposited_players_by_brand(brand_code character varying,
                                                                       start_date timestamp with time zone,
                                                                       end_date timestamp with time zone)
    returns TABLE
            (
                agent                text,
                host                 text,
                playername           text,
                daily_deposit_amount numeric,
                daily_deposit_count  integer,
                first_deposit_on     timestamp with time zone
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT coalesce(a.username, '')::text AS agent,
               coalesce(PIR.host, '')::text   AS host,
               p.username::text               AS playername,
               pdp.daily_deposit_amount,
               pdp.daily_deposit_count,
               pdp.first_deposit_on
        FROM dbo.player_daily_payment_statistics pdp
                 JOIN dbo.players p ON p.player_code = pdp.player_code
                 LEFT JOIN dbo.player_ip_records PIR ON p.player_code = PIR.player_code
            AND PIR.ip_type = 1
                 LEFT JOIN dbo.agents a ON a.id = p.agent_id
        WHERE p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
          AND pdp.first_deposit_on >= start_date
          AND pdp.first_deposit_on < end_date
        ORDER BY 1 NULLS FIRST,
                 2,
                 3;
END;
$$;

create or replace function report.get_registered_players_by_brand(brand_code character varying,
                                                                  start_date timestamp with time zone,
                                                                  end_date timestamp with time zone)
    returns TABLE
            (
                agent         text,
                host          text,
                player        text,
                real_name     text,
                registered_on timestamp with time zone
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT coalesce(a.username, '')::text  AS agent,     -- Coalesce to handle possible NULL values
               coalesce(PIR.host, '')::text    AS host,      -- Coalesce to handle possible NULL values
               p.username::text                AS player,
               coalesce(p.real_name, '')::text AS real_name, -- Coalesce to handle possible NULL values
               p.registered_on
        FROM dbo.players p
                 LEFT JOIN dbo.agents a ON a.id = p.agent_id
                 LEFT JOIN dbo.player_ip_records AS PIR ON p.player_code = PIR.player_code
            AND PIR.ip_type = 1
        WHERE p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
          AND p.registered_on >= start_date
          AND p.registered_on < end_date
        ORDER BY 1 NULLS FIRST, 2, 3; -- Order by agent (NULLS FIRST), host, and player
END;
$$;

create or replace function report.get_promotion_distributions(brand_code character varying,
                                                              start_date timestamp with time zone,
                                                              end_date timestamp with time zone)
    returns TABLE
            (
                username       character varying,
                promotion_name character varying,
                promotion_type text,
                bonus_amount   numeric,
                created_on     text,
                sent_on        text
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        SELECT a.username,
               a.name,
               a.promotion_type,
               a.bonus_amount,
               to_char(a.created_on + interval '8 hours', 'HH24:MI:SS DD/MM/YYYY')            AS created_on,
               COALESCE(to_char(a.sent_on + interval '8 hours', 'HH24:MI:SS DD/MM/YYYY'), '') AS sent_on
        FROM (SELECT p.username,
                     pm.name,
                     pm.promotion_type,
                     pd.bonus_amount,
                     pd.created_on,
                     pd.sent_on
              FROM dbo.promotion_distributes pd
                       JOIN dbo.promotions pm ON pm.id = pd.promotion_id
                       JOIN dbo.players p ON p.player_code = pd.player_code
              WHERE p.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
                AND pd.sent_on >= start_date
                AND pd.sent_on < end_date
              UNION
              SELECT p.username,
                     pm.name,
                     pb.promotion_type,
                     pp.bonus_amount,
                     pb.created_on,
                     pp.sent_on
              FROM dbo.promotion_players pp
                       JOIN dbo.promotion_bonuses pb ON pb.id = pp.promotion_bonus_id
                       JOIN dbo.promotions pm ON pm.id = pb.promotion_id
                       JOIN dbo.players p ON p.player_code = pp.player_code
              WHERE pb.brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
                AND pp.sent_on >= start_date
                AND pp.sent_on < end_date) a
        ORDER BY a.sent_on DESC;
END;
$$;

create or replace function report.get_player_withdraw_count(brand_code character varying, start_date date, end_date date) returns integer
    language plpgsql
as
$$
DECLARE
    withdraw_count INTEGER;
BEGIN
    SELECT COUNT(*)
    INTO withdraw_count
    FROM (SELECT pdps.player_code, COUNT(*) AS cc
          FROM dbo.player_daily_payment_statistics pdps
                   JOIN dbo.players p ON p.player_code = pdps.player_code
                   JOIN dbo.brands b ON p.brand_id = b.id
          WHERE b.code = brand_code
            AND pdps.report_date >= start_date
            AND pdps.report_date < end_date
            AND pdps.daily_withdraw_amount > 0
          GROUP BY pdps.player_code) a
    WHERE a.cc > 0;
    RETURN withdraw_count;
END;
$$;

create or replace function report.get_bonus_player_count(brand_code character varying,
                                                         start_date timestamp with time zone,
                                                         end_date timestamp with time zone) returns integer
    language plpgsql
as
$$
DECLARE
    player_count INTEGER;
BEGIN
    SELECT COUNT(*)
    INTO player_count
    FROM (SELECT player_code,
                 SUM(birthday_amount + season_amount + upgrade_amount + promotion_amount + rebate_amount) AS bonus
          FROM report.player_aggregates
          WHERE brand_id = (SELECT id FROM dbo.brands WHERE code = brand_code)
            AND report_date >= start_date
            AND report_date < end_date
          GROUP BY player_code) a
    WHERE a.bonus > 0;

    RETURN player_count;
END;
$$;

create or replace function report.get_daily_brands_revenue()
    returns TABLE
            (
                platform                       text,
                currency_code                  text,
                date                           date,
                active_users_count             numeric,
                daily_order_count              text,
                daily_revenue_usd              text,
                monthly_cumulative_revenue_usd text
            )
    language plpgsql
as
$$
BEGIN
    RETURN QUERY
        WITH ExchangeRates AS (SELECT 'PHP' AS currency_code, 0.0177 AS rate_to_usd
                               UNION ALL
                               SELECT 'HKD', 0.1277
                               UNION ALL
                               SELECT 'VND_1000', 0.0398),
             SubQuery AS (SELECT b.code                                                                           AS platform,
                                 bc.currency_code,
                                 ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date AS date,
                                 COUNT(DISTINCT p.player_code)                                                    AS active_users_count,
                                 SUM(p.round_count)                                                               AS daily_order_count_raw,
                                 ROUND(SUM(p.win_loss_amount * er.rate_to_usd), 2)                                AS daily_revenue_usd_raw,
                                 SUM(ROUND(SUM(p.win_loss_amount * er.rate_to_usd), 2)) OVER (
                                     PARTITION BY b.code
                                     ORDER BY ((p.report_date::date + INTERVAL '1 day' + INTERVAL '8 hours')::timestamp)::date ASC
                                     )                                                                            AS monthly_cumulative_revenue_usd
                          FROM report.player_aggregates p
                                   JOIN dbo.brands b ON b.id = p.brand_id
                                   JOIN dbo.brand_currencies bc ON b.id = bc.brand_id
                                   LEFT JOIN ExchangeRates er ON bc.currency_code = er.currency_code
                          WHERE
                              p.report_date >= DATE_TRUNC('month', CURRENT_DATE) - INTERVAL '1 day' + INTERVAL '8 hours'
                            AND p.report_date <
                                DATE_TRUNC('month', CURRENT_DATE) + INTERVAL '1 month' + INTERVAL '8 hours'
                            AND p.bet_amount > 0
                            AND b.code NOT IN ('Sky8', 'GPI')
                          GROUP BY b.code, bc.currency_code, date)

        SELECT CAST('Total' AS text)                                                   AS platform,
               CAST('' AS text)                                                        AS currency_code,
               (CURRENT_DATE - INTERVAL '1 day')::date                                 AS date,
               SUM(sq.active_users_count)                                              AS active_users_count,
               TO_CHAR(SUM(sq.daily_order_count_raw), 'FM999,999,999,999')             AS daily_order_count,
               TO_CHAR(SUM(sq.daily_revenue_usd_raw), 'FM999,999,999,999.99')          AS daily_revenue_usd,
               TO_CHAR(SUM(sq.monthly_cumulative_revenue_usd), 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
        FROM SubQuery sq
        WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
        UNION ALL
        SELECT CAST(sq.platform AS text),      -- Cast to text
               CAST(sq.currency_code AS text), -- Cast to text
               sq.date,
               sq.active_users_count,
               TO_CHAR(sq.daily_order_count_raw, 'FM999,999,999,999')             AS daily_order_count,
               TO_CHAR(sq.daily_revenue_usd_raw, 'FM999,999,999,999.99')          AS daily_revenue_usd,
               TO_CHAR(sq.monthly_cumulative_revenue_usd, 'FM999,999,999,999.99') AS monthly_cumulative_revenue_usd
        FROM SubQuery sq
        WHERE sq.date = (CURRENT_DATE - INTERVAL '1 day')::date
        order by 2;
END;
$$;
